14: export default function AddPatientScreen() {
15:   const [name, setName] = useState('');
16:   const [phone, setPhone] = useState('');
17:   const [serviceId, setServiceId] = useState<string | undefined>();
18:   const [consent, setConsent] = useState(false);
19:   const [error, setError] = useState('');
20:   const profile = useAgentProfile();
21:   const services = useAgentServices();
22:   const documents = useAgentDocuments();
23:   const createReferral = useCreateReferral();
24:   const mobile = normalizeIndianMobile(phone);
25:   const consentDocument = useMemo(() => (documents.data ?? []).find((doc) => doc.document_type === 'patient_referral_consent'), [documents.data]);
26: 
27:   async function submit() {
28:     setError('');
29:     if (name.trim().length < 2) { setError('Enter the patient’s full name.'); return; }
30:     if (!isIndianMobile(mobile)) { setError('Enter a valid 10-digit Indian mobile number.'); return; }
31:     if (!profile.data?.branch_id) { setError('Your branch assignment is unavailable. Contact Kezza operations.'); return; }
32:     if (!consentDocument) { setError('Kezza has not published the patient consent text yet. Do not submit patient details until it is available.'); return; }
33:     if (!consent) { setError('Confirm that the patient has agreed to the published consent terms.'); return; }
34:     try {
35:       await createReferral.mutateAsync({
36:         patient_name: name.trim(), patient_phone_e164: toE164(mobile), branch_id: profile.data.branch_id,
37:         ...(serviceId ? { service_id: serviceId } : {}), consent_document_id: consentDocument.id,
38:         consent_accepted: true, idempotency_key: requestKey(),
39:       });
40:     } catch (caught) { setError(getErrorMessage(caught, 'The patient referral could not be saved.')); }
41:   }
42: 
43:   if (createReferral.isSuccess) {
44:     return (
45:       <Screen>
46:         <PageHeading eyebrow="Referral created" title="Patient added" subtitle="The referral is linked to your agent account." />
47:         <Card><Text style={styles.successMark}>✓</Text><Text style={styles.successTitle}>{createReferral.data.patient_name}</Text><Text style={styles.muted}>Reference: {createReferral.data.reference}</Text><Text style={styles.muted}>The patient number is masked in your referral list.</Text></Card>
48:         <Button onPress={() => router.back()}>Done</Button>
49:         <Button variant="secondary" onPress={() => { createReferral.reset(); setName(''); setPhone(''); setServiceId(undefined); setConsent(false); }}>Add another patient</Button>
50:       </Screen>
51:     );
52:   }
53: 
54:   return (
55:     <Screen>
56:       <PageHeading eyebrow="New referral" title="Add a patient" subtitle="Save a referral only after the patient has agreed to Kezza follow-up." />
57:       <Card>
58:         <FormField label="Patient full name" value={name} onChangeText={setName} placeholder="Enter full name" autoCapitalize="words" maxLength={150} />
59:         <FormField label="Mobile number" value={phone} onChangeText={setPhone} placeholder="98765 43210" keyboardType="phone-pad" maxLength={14} />
60:         <View style={styles.fieldGroup}>
61:           <Text style={styles.fieldLabel}>Service interest (optional)</Text>
62:           <View style={styles.options}>
63:             <Option label="Not specified" selected={!serviceId} onPress={() => setServiceId(undefined)} />
64:             {(services.data ?? []).map((item) => <Option key={item.id} label={item.name} selected={serviceId === item.id} onPress={() => setServiceId(item.id)} />)}
65:           </View>
66:           {services.isError ? <InlineNotice tone="error">{getErrorMessage(services.error, 'Could not load Kezza services.')}</InlineNotice> : null}
67:         </View>
68:         {consentDocument ? <View style={styles.consentBox}><Text style={styles.fieldLabel}>{consentDocument.title} · version {consentDocument.version}</Text><Text style={styles.consentBody}>{consentDocument.body}</Text></View> : (
69:           <InlineNotice tone="info">Kezza has not published a patient consent document. Referral creation stays disabled until an approved document is available.</InlineNotice>
70:         )}
71:         <Pressable accessibilityRole="checkbox" accessibilityState={{ checked: consent }} onPress={() => setConsent((current) => !current)} style={styles.consentRow}>
72:           <View style={[styles.checkbox, consent && styles.checked]}>{consent ? <Text style={styles.check}>✓</Text> : null}</View>
73:           <Text style={styles.consentText}>The patient has agreed to the consent terms shown above, and I am recording that agreement accurately.</Text>
74:         </Pressable>
75:         {profile.data?.branch ? <Text style={styles.muted}>Assigned branch: {profile.data.branch.name}</Text> : null}
76:         {error ? <InlineNotice tone="error">{error}</InlineNotice> : null}
77:         <Button onPress={submit} loading={createReferral.isPending} disabled={!consentDocument || !profile.data?.branch_id}>Save patient referral</Button>
78:         <Button variant="quiet" onPress={() => router.back()}>Cancel</Button>
79:       </Card>
80:     </Screen>
81:   );
82: }
83: 
84: function Option({ label, selected, onPress }: { label: string; selected: boolean; onPress: () => void }) {
85:   return <Pressable onPress={onPress} style={[styles.option, selected && styles.optionSelected]}><Text style={[styles.optionText, selected && styles.optionTextSelected]}>{label}</Text></Pressable>;
86: }
